import ProfileCard from './ProfileCard';

function App() {
  // 1. ประกาศตัวแปร members ไว้ตรงนี้ (ก่อน return)
  const members = [
    {
      id: 1,
      name: 'สมชาย สายลุย',
      nickname: 'ชาย',
      major: 'วิทยาการคอมพิวเตอร์',
      favorites: ['เขียนโค้ด', 'เล่นเกม']
    },
    {
      id: 2,
      name: 'สมหญิง รักดี',
      nickname: 'หญิง',
      major: 'เทคโนโลยีสารสนเทศ',
      favorites: ['วาดรูป', 'ฟังเพลง']
    }
  ];

  // 2. ค่อยสั่ง return JSX ออกไป
  return (
    <div className="min-h-screen bg-slate-50 p-8">
      <h1 className="mb-8 text-center text-3xl font-bold text-slate-800">
        สมาชิกกลุ่มของเรา
      </h1>
      <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
        {members.map((m) => (
          <ProfileCard 
            key={m.id} 
            name={m.name} 
            nickname={m.nickname}
            major={m.major} 
            favorites={m.favorites} 
          />
        ))}
      </div>
    </div>
  );
}

export default App;
